return ['domain'=>'simple-ldap-login','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'sv_SE','project-id-version'=>'Simple LDAP Login 2.0.0','pot-creation-date'=>'2026-10-30T15:26:17+00:00','po-revision-date'=>'2026-10-30T15:26:17+00:00','x-generator'=>'WP-CLI 2.12.0','messages'=>['Simple LDAP Login'=>'Simple LDAP Login','https://github.com/clifgriffin/simple-ldap-login'=>'https://github.com/clifgriffin/simple-ldap-login','Connect WordPress accounts to Active Directory or OpenLDAP.'=>'Anslut WordPress-konton till Active Directory eller OpenLDAP.','Clif Griffin Development Inc.'=>'Clif Griffin Development Inc.','https://clifgriffin.com'=>'https://clifgriffin.com','User data'=>'Användardata','Single sign-on'=>'Enkel inloggning','Custom user fields'=>'Anpassade användarfält','Copy LDAP attributes to WordPress user meta fields.'=>'Kopiera LDAP-attribut till WordPress användarmetadatafält.','Field mappings'=>'Fältmappningar','One mapping per line: LDAP attribute:WordPress meta key:type. Example: %1$s. Types: %2$s or %3$s.'=>'Ett mappning per rad: LDAP-attribut:WordPress meta nyckel:typ. Exempel: %1$s. Typer: %2$s eller %3$s.','Custom field storage'=>'Lagring av anpassade fält','Leave the defaults unless your integration uses different user meta keys.'=>'Lämna standardinställningarna om din integration inte använder andra användarmetadata nycklar.','LDAP value suffix'=>'LDAP-värdesuffix','Stores the LDAP value, such as phone_ldap.'=>'Lagrar LDAP-värdet, som phone_ldap.','WordPress value suffix'=>'WordPress-värdesuffix','Stores the editable WordPress value, such as phone_wp.'=>'Lagrar det redigerbara WordPress-värdet, som phone_wp.','Single sign-on (SSO)'=>'Enkel inloggning (SSO)','Your web server must authenticate users and set REMOTE_USER. Never copy a browser header into REMOTE_USER or allow access that bypasses server authentication. Set the LDAP search account on Connection.'=>'Din webbserver måste autentisera användare och ställa in REMOTE_USER. Kopiera aldrig en webbläsarhuvud till REMOTE_USER eller tillåt åtkomst som kringgår serverautentisering. Ställ in LDAP-sökkontot på Anslutning.','Enable automatic login after web server authentication.'=>'Aktivera automatisk inloggning efter webbserverautentisering.','Web server authentication'=>'Webbserverautentisering','REMOTE_USER is present.'=>'REMOTE_USER är närvarande.','REMOTE_USER is missing. Check the web server configuration.'=>'REMOTE_USER saknas. Kontrollera webbserverkonfigurationen.','The update was stopped. Activate Simple LDAP Login Pro to restore LDAP login.'=>'Uppdateringen stoppades. Aktivera Simple LDAP Login Pro för att återställa LDAP-inloggning.','Update blocked: This package does not include all Pro files. To install Free, deactivate the plugin first. Your installed files and settings are unchanged.'=>'Uppdatering blockerad: Detta paket innehåller inte alla Pro-filer. För att installera Free, inaktivera pluginet först. Dina installerade filer och inställningar är oförändrade.','WordPress could not reactivate the plugin.'=>'WordPress kunde inte återaktivera pluginen.','Simple LDAP Login needs PHP 8.1 or later.'=>'Simple LDAP Login kräver PHP 8.1 eller senare.','Plugin files are missing. Reinstall Simple LDAP Login from the release ZIP.'=>'Pluginfiler saknas. Installera om Simple LDAP Login från release ZIP.','You do not have permission to change these settings.'=>'Du har inte behörighet att ändra dessa inställningar.','The settings scope has changed. Open the settings page and try again.'=>'Inställningsomfånget har ändrats. Öppna inställningssidan och försök igen.','You do not have permission to view these settings.'=>'Du har inte behörighet att visa dessa inställningar.','Network settings'=>'Nätverksinställningar','Site settings'=>'Webbplatsinställningar','LDAP login settings'=>'LDAP-inloggningsinställningar','Connect to LDAP, then test a login before enabling authentication.'=>'Anslut till LDAP, testa sedan en inloggning innan autentisering aktiveras.','LDAP login and SSO are disabled by SLL_DISABLE_LDAP in wp-config.php.'=>'LDAP-inloggning och SSO är inaktiverade av SLL_DISABLE_LDAP i wp-config.php.','Your saved settings use SSO or custom user fields. Install Simple LDAP Login Pro to use these features. Your settings are kept.'=>'Dina sparade inställningar använder SSO eller anpassade användarfält. Installera Simple LDAP Login Pro för att använda dessa funktioner. Dina inställningar sparas.','The saved LDAP search password cannot be read. Enter it again on the Connection tab.'=>'Det sparade LDAP-sökordet kan inte läsas. Ange det igen på fliken Anslutning.','PHP LDAP is missing. Ask your host to install it before enabling LDAP login.'=>'PHP LDAP saknas. Be din värd att installera det innan LDAP-inloggning aktiveras.','LDAP passwords are sent without encryption. Use StartTLS or LDAPS if your server supports it.'=>'LDAP-lösenord skickas utan kryptering. Använd StartTLS eller LDAPS om din server stöder det.','Save settings'=>'Spara inställningar','Settings on other tabs are kept.'=>'Inställningar på andra flikar sparas.','LDAP connection'=>'LDAP-anslutning','LDAP login'=>'LDAP-inloggning','Enable LDAP authentication.'=>'Aktivera LDAP-autentisering.','Directory type'=>'Katalogtyp','Active Directory'=>'Active Directory','OpenLDAP / other LDAP directory'=>'OpenLDAP / annan LDAP-katalog','LDAP servers'=>'LDAP-servrar','One hostname or IP address per line. Servers are tried in order.'=>'Ett värdnamn eller IP-adress per rad. Servrar prövas i ordning.','Base DN'=>'Bas DN','Where to search for users. Example: DC=example,DC=org.'=>'Var du ska söka efter användare. Exempel: DC=example,DC=org.','Username suffix'=>'Användarnamn suffix','Added to usernames without a domain. Example: @example.org.'=>'Läggs till användarnamn utan domän. Exempel: @example.org.','Windows domain'=>'Windows-domän','Short domain name, such as EXAMPLE. Takes priority over the username suffix.'=>'Kort domännamn, som EXAMPLE. Har företräde framför användarnamn suffix.','Connection security'=>'Anslutningssäkerhet','TLS requires a trusted server certificate.'=>'TLS kräver ett betrott servercertifikat.','StartTLS (recommended)'=>'StartTLS (rekommenderas)','LDAPS'=>'LDAPS','Unencrypted LDAP'=>'Okrypterad LDAP','Unencrypted LDAP requires permission on the Advanced tab.'=>'Okrypterad LDAP kräver tillstånd på fliken Avancerat.','Port'=>'Port','389 for StartTLS; 636 for LDAPS.'=>'389 för StartTLS; 636 för LDAPS.','Search subfolders'=>'Sök i undermappar','Search all organizational units below the Base DN.'=>'Sök i alla organisatoriska enheter under Bas DN.','LDAP search account'=>'LDAP-sökkonto','An LDAP account with read access to users and groups.'=>'Ett LDAP-konto med läsbehörighet till användare och grupper.','Search account'=>'Sökkonto','LDAP bind DN or account name.'=>'LDAP bind DN eller kontonamn.','Search account password'=>'Lösenord för sökonto','Leave blank to keep the saved password.'=>'Lämna tomt för att behålla det sparade lösenordet.','Login rules'=>'Inloggningsregler','Require LDAP passwords'=>'Kräv LDAP-lösenord','Block WordPress passwords except for recovery access.'=>'Blockera WordPress-lösenord utom för återställningstillgång.','Local recovery access'=>'Lokal återställningstillgång','Selected administrators'=>'Valda administratörer','All super administrators (legacy)'=>'Alla superadministratörer (legacy)','All administrators (legacy)'=>'Alla administratörer (legacy)','Off'=>'Av','Choose who can use a WordPress password when LDAP passwords are required.'=>'Välj vem som kan använda ett WordPress-lösenord när LDAP-lösenord krävs.','Automatic account creation'=>'Automatisk kontoskapande','Create a WordPress account on the first successful LDAP login.'=>'Skapa ett WordPress-konto vid första lyckade LDAP-inloggning.','Default role'=>'Standardroll','For new accounts only.'=>'Endast för nya konton.','Required groups'=>'Krävda grupper','One group name per line. Users must belong to at least one. Leave blank to allow all LDAP users.'=>'Ett gruppnamn per rad. Användare måste tillhöra minst en. Lämna tomt för att tillåta alla LDAP-användare.','Recovery accounts'=>'Återställningskonton','For Selected administrators only. Use separate local accounts with WordPress passwords. Hold Ctrl or Command to select multiple accounts.'=>'Endast för valda administratörer. Använd separata lokala konton med WordPress-lösenord. Håll Ctrl eller Command för att välja flera konton.','Connection options'=>'Anslutningsalternativ','Change these only if the default values do not work with your directory.'=>'Ändra dessa endast om standardvärdena inte fungerar med din katalog.','LDAP timeout (seconds)'=>'LDAP timeout (sekunder)','Maximum wait for an LDAP operation. Default: 5 seconds.'=>'Maximal väntetid för en LDAP-operation. Standard: 5 sekunder.','Login attribute'=>'Inloggningsattribut','Attribute used to find users. Default: uid.'=>'Attribut som används för att hitta användare. Standard: uid.','Allow unencrypted LDAP'=>'Tillåt okrypterad LDAP','Allow passwords to be sent without encryption.'=>'Tillåt lösenord att skickas utan kryptering.','Group search'=>'Gruppsökning','Group base DN'=>'Gruppbas DN','Leave blank to use the user Base DN.'=>'Lämna tomt för att använda användarens bas DN.','Group name attribute'=>'Gruppnamnsattribut','Default: cn.'=>'Standard: cn.','Group member attribute'=>'Gruppmedlemsattribut','Default: memberUid. Use member or uniqueMember if groups store user DNs.'=>'Standard: memberUid. Använd member eller uniqueMember om grupper lagrar användar-DN:er.','Profile attributes'=>'Profilattribut','LDAP attributes copied to new WordPress accounts.'=>'LDAP-attribut kopieras till nya WordPress-konton.','First name attribute'=>'Förnamnsattribut','Last name attribute'=>'Efternamnsattribut','Email attribute'=>'E-postattribut','Website attribute'=>'Webbplatsattribut','Data retention'=>'Dataretention','Delete settings when removing the plugin'=>'Ta bort inställningar när plugin-programmet tas bort','Delete saved settings and LDAP credentials when WordPress deletes the plugin. Keep user accounts.'=>'Ta bort sparade inställningar och LDAP-referenser när WordPress tar bort plugin-programmet. Behåll användarkonton.','Test LDAP login'=>'Testa LDAP-inloggning','Save your settings, then run both tests. Keep this administrator session open.'=>'Spara dina inställningar, kör sedan båda testerna. Håll denna administratörssession öppen.','Tests check the connection, password, and required groups. They do not create accounts or sign users in.'=>'Tester kontrollerar anslutningen, lösenordet och nödvändiga grupper. De skapar inte konton eller loggar in användare.','After both tests pass, enable LDAP and try logging in from another browser.'=>'När båda testerna har godkänts, aktivera LDAP och försök logga in från en annan webbläsare.','Recovery'=>'Återställning','If you are locked out, rename the simple-ldap-login folder using your hosting file manager. Log in with a WordPress administrator password, then restore the folder and correct the settings.'=>'Om du är utelåst, döp om mappen simple-ldap-login med din värdtjänsts filhanterare. Logga in med ett WordPress-administratörslösenord, återställ sedan mappen och korrigera inställningarna.','For certificate errors, ask your host to configure the trusted LDAP certificate authority.'=>'För certifikatfel, be din värd att konfigurera den betrodda LDAP-certifikatmyndigheten.','LDAP tests'=>'LDAP-tester','Tests use saved settings.'=>'Tester använder sparade inställningar.','1. Test connection'=>'1. Testa anslutning','Connect to LDAP and test the search account, if set.'=>'Anslut till LDAP och testa sökkontot, om det är inställt.','Test connection'=>'Testa anslutning','2. Test login'=>'2. Testa inloggning','Check an LDAP username, password, and group membership.'=>'Kontrollera ett LDAP-användarnamn, lösenord och gruppmedlemskap.','LDAP username'=>'LDAP-användarnamn','LDAP password'=>'LDAP-lösenord','Settings saved.'=>'Inställningar sparade.','Connection test passed.'=>'Anslutningstest godkänt.','Cannot connect to LDAP. Check the server, port, TLS certificate, and search account.'=>'Kan inte ansluta till LDAP. Kontrollera servern, porten, TLS-certifikatet och sökkontot.','LDAP login test passed. No account was created.'=>'LDAP-inloggningstest godkänt. Inget konto skapades.','LDAP login test failed. Check the username, password, and required groups.'=>'LDAP-inloggningstest misslyckades. Kontrollera användarnamn, lösenord och nödvändiga grupper.','Could not save settings. Check the values and try again.'=>'Kunde inte spara inställningar. Kontrollera värdena och försök igen.','Connection'=>'Anslutning','Access'=>'Åtkomst','Advanced'=>'Avancerat','Troubleshooting'=>'Felsökning','Your LDAP login is valid, but you need a WordPress account. Contact your site administrator.'=>'Din LDAP-inloggning är giltig, men du behöver ett WordPress-konto. Kontakta din webbplatsadministratör.','Your LDAP username is not a valid WordPress username. Contact your site administrator.'=>'Ditt LDAP-användarnamn är inte ett giltigt WordPress-användarnamn. Kontakta din webbplatsadministratör.','The default WordPress role is not available. Contact your site administrator.'=>'Den standard WordPress-roll är inte tillgänglig. Kontakta din webbplatsadministratör.','Could not create your WordPress account. Contact your site administrator.'=>'Kunde inte skapa ditt WordPress-konto. Kontakta din webbplatsadministratör.','Use your WordPress password for this recovery account.'=>'Använd ditt WordPress-lösenord för detta återställningskonto.','LDAP login failed. Check your username and password or contact your site administrator.'=>'LDAP-inloggning misslyckades. Kontrollera ditt användarnamn och lösenord eller kontakta din webbplatsadministratör.','Your account is not allowed to log in to this site.'=>'Ditt konto har inte behörighet att logga in på denna webbplats.','LDAP login is unavailable. Contact your site administrator.'=>'LDAP-inloggning är inte tillgänglig. Kontakta din webbplatsadministratör.','PHP OpenSSL is required to save the LDAP search password.'=>'PHP OpenSSL krävs för att spara LDAP-sökpasswordet.','Could not read or save the LDAP search password. Enter it again. If this continues, ask your host to check OpenSSL and the encryption key.'=>'Kunde inte läsa eller spara LDAP-sökpasswordet. Ange det igen. Om detta fortsätter, be din värd att kontrollera OpenSSL och krypteringsnyckeln.','Select a recovery account on the Access tab, or turn local recovery access Off.'=>'Välj ett återställningskonto på Åtkomst-fliken, eller stäng av lokal återställningsåtkomst.','Enable Allow unencrypted LDAP on the Advanced tab, or choose StartTLS or LDAPS.'=>'Aktivera Tillåt okrypterad LDAP på Avancerat-fliken, eller välj StartTLS eller LDAPS.','A custom field mapping uses a protected or invalid WordPress user meta key.'=>'En anpassad fältmappning använder en skyddad eller ogiltig WordPress användarmeta-nyckel.','Enter a Base DN and at least one LDAP server before enabling LDAP login.'=>'Ange en Bas DN och minst en LDAP-server innan du aktiverar LDAP-inloggning.','WordPress could not save the settings. Try again.'=>'WordPress kunde inte spara inställningarna. Försök igen.','LDAP protocol version'=>'LDAP-protokollversion','LDAP timeout'=>'LDAP-tidsgräns','Check the submitted settings. No changes were saved.'=>'Kontrollera de inskickade inställningarna. Inga ändringar sparades.','Check %s. No changes were saved.'=>'Kontrollera %s. Inga ändringar sparades.']];